function navKey(screen){const value=String(screen?.nav||screen?.group||'').toLowerCase();if(/software|^по$|версии|компонент|registry|каталог/.test(value))return'software';if(/log|журнал/.test(value))return'logs';if(/job|задан|операц/.test(value))return'jobs';if(/setting|настрой|locald|подключение.*служб/.test(value))return'settings';return'servers';}
function current(){return screens.find(s=>s.id===state.screenId)||screens[0];}
function badge(value){const text=String(value);let type='',symbol='●';if(/недоступ|ошиб|отклон|failed|error|отозван|запрещ|не выполн/i.test(text)){type='error';symbol='×';}else if(/предуп|вниман|устар|изменён|изменен|drift|warning/i.test(text)){type='warning';symbol='△';}else if(/неизвест|нет данных|не провер|unknown|ожида|не настро/i.test(text)){type='unknown';symbol='?';}else if(/выполня|проверя|подключа|созда|running|в очеред|готов к|ожидает.*подтв/i.test(text)){type='running';symbol='◔';}else if(/доступ|успех|актуаль|выполн|актив|готов|подтверж|success|установлен|совпадает|enabled/i.test(text)){type='';symbol='✓';}else{return`<span class="status neutral"><i aria-hidden="true">○</i>${esc(text)}</span>`;}return`<span class="status ${type}"><i aria-hidden="true">${symbol}</i>${esc(text)}</span>`;}

function spark(seed=0,color='var(--accent)',series='cpu'){
  const values=[29,26,30,20,24,17,19,9,15,12,18,8,13,7,11,5,9,4,12,7];
  const ys=values.map((v,i)=>Math.max(3,Math.min(32,v+Math.sin(i+seed)*8)));
  const line=ys.map((y,i)=>`${(3+i*184/(ys.length-1)).toFixed(1)},${y.toFixed(1)}`).join(' ');
  const lastY=ys[ys.length-1];
  const memory=/memory|ram/i.test(series),disk=/disk/i.test(series);
  const dash=memory?'stroke-dasharray="5 3"':disk?'stroke-dasharray="1 3"':'';
  const marker=memory?`<rect x="184.5" y="${lastY-2.5}" width="5" height="5" fill="currentColor"/>`:disk?`<path class="spark-marker" d="M187 ${lastY-3.5} l3.5 6 h-7 Z" style="fill:currentColor;stroke:none"/>`:`<circle cx="187" cy="${lastY}" r="2.5" fill="currentColor"/>`;
  return`<svg class="sparkline" viewBox="0 0 194 38" preserveAspectRatio="none" style="color:${color}" aria-label="Демонстрационная динамика за последние 10 минут: ${memory?'RAM':disk?'диска':'CPU'}"><path class="spark-fill" d="M3 38 L${line.replaceAll(' ',' L')} L187 38 Z"/><path class="spark-trend" ${dash} d="M${line.replaceAll(' ',' L')}"/>${marker}</svg>`;
}
function chart(seed=0,secondary=false){const points=[80,86,74,78,54,60,45,51,40,47,32,44,28,35,20,29,21,36,26,32,18,24,20,30];const coords=points.map((v,i)=>`${(i*100/23).toFixed(2)},${(v+Math.sin(i+seed)*13).toFixed(2)}`);const path=`M${coords.join(' L')}`;const second=points.map((v,i)=>`${(i*100/23).toFixed(2)},${(60+Math.cos(i/2+seed)*14).toFixed(2)}`);return`<div class="chart"><div class="chart-grid"><span><i>100</i></span><span><i>75</i></span><span><i>50</i></span><span><i>25</i></span><span><i>0</i></span></div><svg viewBox="0 0 100 100" preserveAspectRatio="none" role="img" aria-label="Демонстрационный график за последние 10 минут"><path class="area" d="${path} L100 100 L0 100 Z"/><path class="line" d="${path}"/>${secondary?`<path class="line secondary" d="M${second.join(' L')}"/>`:''}</svg><div class="chart-axis"><span>12:30</span><span>12:35</span><span>12:40</span></div></div>`;}
function button(label,primary=false,ico=''){return window.DeckDesign.button(label,{variant:primary?'filled':'outlined',icon:ico?icon(ico):'',attributes:`data-demo="${esc(label)}"`});}
function panel(title,body,subtitle='',extra='',classes=''){return window.DeckDesign.surface(title,body,{subtitle,trailing:extra,classes});}
function freshness(source='SSH · edge-01'){return`<div class="data-freshness">${icon('clock')}<span>Снимок данных · 25.10.2026, 12:40:18 MSK</span><span>${esc(source)}</span></div>`;}
function stat(label,value,unit,foot,seed,color='var(--accent)',ico='server'){return`<article class="stat-card"><div class="stat-label">${esc(label)}${icon(ico)}</div><div class="stat-value">${esc(value)}<small>${esc(unit)}</small></div><div class="stat-foot ${/вним|недост|предуп/.test(foot)?'warning':'positive'}">${esc(foot)}</div>${spark(seed,color,ico)}</article>`;}
function stats(section){if(section==='software')return`<div class="stats-grid">${stat('Компоненты','12','','На 4 серверах',1,'var(--accent)','package')}${stat('Актуальные','9','','Проверены по каталогу',5,'var(--available)','check')}${stat('Обновления','3','','Доступны новые версии',9,'var(--chart2)','refresh')}${stat('Проверка','12:40','','Снимок версии каталога',3,'var(--running)','clock')}</div>`;if(section==='jobs')return`<div class="stats-grid">${stat('Выполняются','1','','Сейчас в работе',1,'var(--running)','jobs')}${stat('В очереди','2','','Ожидают запуска',4,'var(--chart2)','clock')}${stat('Завершены','24','','За последние 24 часа',7,'var(--available)','check')}${stat('Требуют внимания','1','','Результат неизвестен',10,'var(--warning)','warning')}</div>`;return`<div class="stats-grid">${stat('Всего серверов','4','','3 доступны по SSH',1,'var(--accent)','server')}${stat('Средняя CPU','34','%','−6% за последний час',5,'var(--running)','cpu')}${stat('Память','20.7','ГБ','из 40 ГБ доступных',9,'var(--chart2)','memory')}${stat('Требуют внимания','2','','1 предупреждение · 1 offline',3,'var(--warning)','warning')}</div>`;}
function filters(screen,placeholder='Поиск по имени, адресу или тегу'){return`<div class="filters"><label class="search-field">${icon('search')}<input type="search" data-filter-input placeholder="${esc(placeholder)}" aria-label="Поиск в макете"></label><div class="filter-group"><button type="button" class="filter-chip active" data-filter="all">Все <span>${screen.rows?.length||4}</span></button><button type="button" class="filter-chip" data-filter="available">${icon('filter')}Состояние</button><button type="button" class="filter-chip" data-demo="Фильтр по тегам">Теги ${icon('chevron')}</button></div></div>`;}
function cell(value,column,index){const str=String(value??'—');if(/состоя|статус|результат|связь|доступность/i.test(column))return badge(str);if(/^\d+(?:[.,]\d+)?\s*%$/.test(str)){const number=parseFloat(str.replace(',','.'));return`<span class="mini-metric">${esc(str)}</span><div class="meter ${number>85?'error':number>70?'warn':''}" aria-hidden="true"><span style="--value:${Math.min(number,100)}%"></span></div>`;}if(/^(?:\d{1,3}\.){3}\d{1,3}(?::\d+)?$/.test(str)||/версия|адрес|порт|pid|код|значение/i.test(column))return`<span class="mono">${esc(str)}</span>`;if(/тег|окружение/i.test(column))return`<span class="tag">${esc(str)}</span>`;if(index===0&&/edge-|api-|db-|worker-/.test(str))return`<span>${esc(str)}</span><span class="secondary">${/db-/.test(str)?'База данных':/worker-/.test(str)?'Фоновая обработка':'Production · Linux'}</span>`;return esc(str);}
function table(screen,override){const columns=(override?.columns||(screen.columns?.length?screen.columns:null)||['Имя','Адрес','Система','Состояние','CPU','RAM']).map(col=>labelOf(col)||String(col));const rows=override?.rows||(screen.rows?.length?screen.rows:null)||sampleServers;return window.DeckDesign.table({columns,rows,cell});}
function activity(){return panel('Последние события',`<div class="panel-body"><div class="activity-item"><span class="activity-symbol">${icon('check')}</span><p>Снимок edge-01 получен<small>Система, ресурсы и версии компонентов</small></p><time>12:40</time></div><div class="activity-item"><span class="activity-symbol" style="color:var(--warning)">${icon('warning')}</span><p>db-01: память выше порога<small>Используется 78% · порог 75%</small></p><time>12:38</time></div><div class="activity-item"><span class="activity-symbol">${icon('package')}</span><p>Проверены версии компонентов<small>Доступны 3 обновления</small></p><time>12:35</time></div></div>`,'Что изменилось в инфраструктуре',`<button class="tiny-link" data-nav="logs">Журнал ${icon('arrow')}</button>`);}
function storage(){return panel('Использование дисков',`<div class="panel-body">${[['edge-01','/ · ext4','42 ГБ / 120 ГБ',35],['api-01','/ · ext4','61 ГБ / 160 ГБ',38],['db-01','/data · xfs','384 ГБ / 500 ГБ',77]].map(([name,mount,value,pct])=>`<div class="storage-row">${icon('disk')}<div><strong>${name} <small>${mount}</small></strong><div class="storage-bar ${pct>70?'warning':''}"><span style="width:${pct}%"></span></div></div><span class="mono">${value}</span></div>`).join('')}</div>`,'Последний полученный снимок');}
function dashboard(screen){const isServer=navKey(screen)==='servers';return`${isServer?`<section class="summary-banner"><span class="banner-icon">${icon('shield')}</span><div class="banner-copy"><h2>Инфраструктура под контролем</h2><p>Три сервера доступны. Два события требуют внимания.</p></div><div class="banner-number">3/4<small>доступны по SSH</small></div></section>`:''}${stats(navKey(screen))}${filters(screen)}${table(screen)}<div class="two-columns">${activity()}${storage()}</div>${freshness('SSH · 4 демо-профиля')}`;}
function tableScreen(screen){const section=navKey(screen);return`${['servers','software','jobs'].includes(section)?stats(section):''}${filters(screen,section==='software'?'Найти компонент или версию':section==='jobs'?'Найти задание, план или сервер':'Поиск по имени, адресу или тегу')}${table(screen)}${section==='software'?notice('Каталог проверен','Версии показаны на момент последней успешной проверки. Перед установкой будет сформирован план действий.','info'):''}${freshness(section==='software'?'Каталог компонентов · снимок 12:35':section==='jobs'?'Локальная история заданий':'SSH · демонстрационные профили')}`;}
function tabs(screen,fallback){const list=screen.tabs?.length?screen.tabs:fallback;return list?.length?`<nav class="tabs" aria-label="Разделы экрана">${list.map((tab,i)=>`<button type="button" class="tab ${i===0?'active':''}" data-tab="${esc(labelOf(tab))}">${esc(labelOf(tab))}</button>`).join('')}</nav>`:'';}
function listFields(screen,fallback){const fields=screen.fields?.length?screen.fields:fallback;return`<dl class="description-list">${fields.map(f=>`<dt>${esc(f.label)}</dt><dd>${/состоя|статус|результат/i.test(f.label)?badge(f.value):esc(f.value??'—')}</dd>`).join('')}</dl>`;}
function resourceCards(cards=[['CPU','24','%','4 ядра · load 0.62','cpu',1,'var(--accent)'],['Память','3.2','/ 8 ГБ','40% от общего объёма','memory',6,'var(--chart2)'],['Диск /','42','/ 120 ГБ','35% · 78 ГБ свободно','disk',11,'var(--running)']]){return`<div class="resource-grid">${cards.map(([label,value,unit,description,ico,seed,color])=>`<article class="resource-card"><h3>${label}${icon(ico)}</h3><div class="resource-number">${value}<small>${unit}</small></div><p class="resource-detail">${description}</p>${spark(seed,color,ico)}</article>`).join('')}</div>`;}
function detail(screen){const isServer=navKey(screen)==='servers';if(!isServer)return componentDetail(screen);return`<div class="server-identity"><div class="server-emblem">${icon('server')}</div><div class="identity-content"><h2>edge-01</h2><p><span class="mono">192.0.2.11:22</span> · production · web</p></div>${badge('Доступен по SSH')}</div>${tabs(screen,['Обзор','Ресурсы','ПО и версии','Журнал','Настройки'])}${resourceCards()}<div class="two-columns equal">${panel('Система',`<div class="panel-body">${listFields(screen,[{label:'Операционная система',value:'Ubuntu 24.04 LTS'},{label:'Ядро',value:'6.8.0-45-generic'},{label:'Архитектура',value:'x86_64'},{label:'Hostname',value:'edge-01.example.test'},{label:'Время работы',value:'18 д 4 ч 32 мин'},{label:'Последний снимок',value:'25.10.2026 12:40:18 MSK'}])}</div>`)}${panel('Процессор за последний час',`<div class="panel-body">${chart(1)}<div class="chart-legend"><span><i></i>CPU, %</span><span><i></i>Средняя нагрузка</span></div></div>`,'Шаг измерения · 30 секунд')}</div>${panel('Компоненты',`<div class="panel-body"><div class="storage-row">${icon('package')}<div><strong>nginx</strong><small>Системный пакет · web</small></div><span class="mono">1.24.0</span>${badge('Актуальная')}</div><div class="storage-row">${icon('package')}<div><strong>Docker Engine</strong><small>Контейнерная среда</small></div><span class="mono">27.3.1</span>${badge('Доступно обновление')}</div></div>`,'Версии из последнего снимка',`<button type="button" class="tiny-link" data-nav="software">Все компоненты →</button>`)}${freshness()}`;}
function componentDetail(screen){return`${tabs(screen,['Обзор','Версии','Зависимости','История'])}<div class="server-identity"><div class="server-emblem">${icon('package')}</div><div class="identity-content"><h2>${esc(/nginx|docker|postgres|redis/i.exec(screen.title)?.[0]||'nginx')}</h2><p>Системный компонент · edge-01</p></div>${badge('Установлен')}</div><div class="two-columns equal">${panel('Информация о компоненте',`<div class="panel-body">${listFields(screen,[{label:'Установленная версия',value:'1.24.0'},{label:'Доступная версия',value:'1.26.2'},{label:'Источник',value:'Официальный репозиторий'},{label:'Способ установки',value:'apt'},{label:'Последняя проверка',value:'25.10.2026 12:35 MSK'}])}</div>`)}${panel('Доступное действие',`<div class="panel-body"><h3>Обновить компонент</h3><p class="page-description">Сначала сформируйте и проверьте план. Вы увидите зависимости, изменения и возможную остановку сервисов.</p><div style="margin-top:16px">${button('Подготовить план',true,'jobs')}</div></div>`,'Обновление по подтверждённому плану')}</div>${panel('Зависимости',`<div class="panel-body"><div class="status-check"><span>${icon('package')}libc6 ≥ 2.38</span>${badge('Установлен')}</div><div class="status-check"><span>${icon('package')}libssl3 ≥ 3.0</span>${badge('Установлен')}</div><div class="status-check"><span>${icon('disk')}Свободное место · 120 МБ</span>${badge('Достаточно')}</div></div>`)}${freshness('Каталог компонентов · демо')}`;}
function notice(title,message,type='info'){return window.DeckDesign.notice(title,message,{tone:type,icon:icon(type==='success'?'check':type==='error'?'close':type==='warning'?'warning':'info')});}

function fieldHTML(field,index){
  const label=String(field.label||`Поле ${index+1}`);
  const value=String(field.value??'');
  const numericValue=/^[+-]?(?:\d+(?:\.\d+)?|\.\d+)$/.test(value.trim());
  const sshContext=/^(07-profile-create|08-profile-edit|12-credential-input)$/.test(current()?.id||'');
  const sshPort=/^порт\s+ssh$/i.test(label)||(sshContext&&/^порт$/i.test(label));
  let inferred=field.type||(/парол|passphrase|токен|секрет/i.test(label)?'password':/порт|интервал|секунд|размер|лимит/i.test(label)&&numericValue?'number':/ключ|команд|сценарий|описание|fingerprint|отпечаток/i.test(label)?'textarea':'text');
  // Number inputs discard non-numeric strings in the browser. Keep units and
  // mappings visible, even if the manifest supplied a numeric field type.
  if(inferred==='number'&&!numericValue)inferred='text';
  const id=`field-${index}`;
  const required=index<2;
  let control;
  if(inferred==='select'||/аутентификац|способ.*подключ|способ.*доступ|тип подключения|режим|платформа|источник/i.test(label)){
    const opts=[value||'По ключу SSH',...(/аутентиф|подключ|способ.*доступ/i.test(label)?['По ключу SSH','Пароль']:['По умолчанию','Вручную'])].filter((v,i,a)=>a.indexOf(v)===i);
    control=`<select id="${id}" name="${id}">${opts.map(v=>`<option>${esc(v)}</option>`).join('')}</select>`;
  }else if(inferred==='textarea'){
    control=`<textarea id="${id}" name="${id}" spellcheck="false">${esc(value)}</textarea>`;
  }else if(inferred==='checkbox'||inferred==='toggle'){
    control=`<button type="button" role="switch" aria-checked="true" class="toggle on" aria-label="${esc(label)}" data-toggle></button>`;
  }else{
    const type=['text','password','number','email','url'].includes(inferred)?inferred:'text';
    const range=type==='number'&&sshPort?'min="1" max="65535"':'';
    control=`<input id="${id}" name="${id}" type="${type}" value="${esc(value)}" ${required?'required':''} ${type==='password'?'autocomplete="new-password"':'autocomplete="off"'} ${range}>`;
  }
  let hint='';
  if(/адрес|host|хост/i.test(label))hint='IP-адрес или доменное имя сервера';
  if(sshPort)hint='Стандартный порт SSH — 22';
  if(/парол|ключ|токен/i.test(label))hint='В макете используется вымышленное значение';
  return window.DeckDesign.field(label+(required?' *':''),control,{id,hint,full:inferred==='textarea'});
}
function formScreen(screen){const fields=screen.fields?.length?screen.fields:[{label:'Имя сервера',value:'edge-02'},{label:'Адрес',value:'192.0.2.15'},{label:'Порт SSH',value:'22',type:'number'},{label:'Пользователь',value:'deploy'},{label:'Способ аутентификации',value:'По ключу SSH',type:'select'},{label:'Метка ключа',value:'Рабочий SSH-ключ'},{label:'Теги',value:'production, web'}];const title=/редакт|измен|настрой/i.test(screen.title)?'Параметры подключения':'Данные подключения';return`${/удал|отозв|опасн|confirm|подтверж/i.test(screen.id+' '+screen.title)?notice('Проверьте действие перед подтверждением','Убедитесь, что выбран правильный сервер. В макете подтверждение изменит только демонстрационное состояние.','warning'):''}<div class="form-layout"><form class="panel demo-form"><section class="form-section"><h2>${title}</h2><p>Укажите параметры, которые будут использоваться для подключения к серверу.</p><div class="form-grid">${fields.map(fieldHTML).join('')}</div></section><section class="form-section"><h2>Проверка перед сохранением</h2><p>Подключение и отпечаток узла проверяются отдельно. Профиль сохраняется после вашего подтверждения.</p><div class="setting-row"><div><h3>Проверить подключение</h3><p>Убедиться, что сервер доступен с указанными параметрами</p></div><button class="toggle on" type="button" role="switch" aria-checked="true" aria-label="Проверить подключение" data-toggle></button></div></section><div class="form-actions">${button('Отмена',false)}<button type="submit" class="button primary">${icon('check')}${esc(labelOf(screen.actions?.[0])||'Проверить и сохранить')}</button></div></form><aside class="helper-panel"><div class="helper-icon">${icon('shield')}</div><h3>Подключение под вашим контролем</h3><p>Проверьте адрес и пользователя. При первом соединении сравните отпечаток ключа с известным вам значением.</p><p>Все поля в этом макете можно редактировать. Они сохраняются при переключении темы и размера.</p><dl class="description-list"><dt>Пример адреса</dt><dd>192.0.2.15</dd><dt>Протокол</dt><dd>SSH</dd><dt>Метка окружения</dt><dd>production</dd></dl></aside></div>`;}
