document.addEventListener('click',event=>{const trigger=event.target.closest('[data-open-profile]');if(trigger){const profile=trigger.dataset.openProfile||trigger.closest('[data-profile-card]')?.dataset.profileName;if(profile==='atlas-web')selectScreen('06-server-overview');else showProfileDemo(profile,'Открыть профиль');}if(event.target.closest('[data-software-scope-clear]')){state.softwareServer=null;selectScreen('14-software-inventory');}});
