  '18-install-preflight':{'Просмотреть план':'19-plan-approval'},
  '23-log-record':{'Закрыть':'22-server-logs'},
  '52-backup-schedule':{'Показать сохраняемые копии':'98-retention-preview'},
  '53-files':{'Найти':'54-file-search'},
  '57-updates':{'Подготовить план':'59-package-change-plan','Открыть источники':'58-package-sources'},
