function recordContext(screen,row){
  const fields=(screen.fields||[]).map(item=>`${item.label}: ${item.value}`);
  const record=row?(screen.columns||[]).map((column,i)=>`${labelOf(column)||column}: ${row[i]??'—'}`):[];
  return [...fields,...record].join('\n');
}
function showProfileDemo(profile,action){
  const screen=screens.find(item=>item.id==='05-server-list');
  const row=screen?.rows?.find(item=>item[0]===profile);
  showDemo(action,`Выбранный профиль:\n${row?recordContext(screen,row):profile||'Профиль не выбран'}\n\nЭто демонстрация. Реальное действие не выполняется.`);
}
function openRecordDemo(screen,index){
  const row=screen.rows?.[index];
  if(!row){showDemo('Запись недоступна','Для выбранной записи нет демонстрационных данных.');return;}
  const route=screenRecordRoutes[screen.id]?.[String(row[0])];
  if(route&&screens.some(item=>item.id===route)){selectScreen(route);return;}
  showDemo(String(row[0]),`Выбранная запись:\n${recordContext(screen,row)}\n\nДля этого объекта отдельный макет не представлен. Реальное действие не выполняется.`);
}
function handleDemoAction(action,target){
  const screen=resolvedTableScreen(current());
  const profile=target.closest('[data-profile-card]')?.dataset.profileName;
  if(profile){
    if(action==='Открыть сервер'&&profile==='atlas-web'){selectScreen('06-server-overview');return;}
    if(action==='Изменить'&&profile==='atlas-web'){selectScreen('08-profile-edit');return;}
    showProfileDemo(profile,action);return;
  }
  const route=screenActionRoutes[screen.id]?.[action];
  if(route&&screens.some(item=>item.id===route)){if(screen.id==='06-server-overview'&&route==='14-software-inventory')openSoftwareScope('atlas-web');else selectScreen(route);return;}
  if(action==='Найти сервер'||action==='Поиск'){
    const input=$('[data-filter-input],[data-log-search]');
    if(input){input.focus();notify('Введите запрос для поиска в демонстрационных данных.');return;}
  }
  if(/^обновить|^проверить версии$/i.test(action)){
    notify('Демонстрационная проверка завершена. Снимок выбранного источника сохранён.');return;
  }
  const context=recordContext(screen);
  showDemo(action,`${screen.title}${context?'\n\n'+context:''}\n\nДемонстрация действия «${action}». Реальная операция не выполняется; выбранная цель не изменяется.`);
}

init();
